    def value(i, j, k):
        a = A[i]
        b = B[j]
        c = C[k]
        return a * b + b * c + c * a

    heap = [(-value(0, 0, 0), 0, 0, 0)]
    seen = {(0, 0, 0)}

    ans = 0
    for _ in range(K):
        neg, i, j, k = heapq.heappop(heap)
        ans = -neg

