            heapq.heappush(heap, (-value(i + 1, j, k), i + 1, j, k))

        if j + 1 < N and (i, j + 1, k) not in seen:
            seen.add((i, j + 1, k))
            heapq.heappush(heap, (-value(i, j + 1, k), i, j + 1, k))

        if k + 1 < N and (i, j, k + 1) not in seen:
            seen.add((i, j, k + 1))
            heapq.heappush(heap, (-value(i, j, k + 1), i, j, k + 1))

    print(ans)

if __name__ == "__main__":
    solve()
